ALTER TABLE "produccion"."ordenes" ADD CONSTRAINT "orden_destino_adelanto" CHECK ("produccion"."ordenes"."destino_adelanto" is null or "produccion"."ordenes"."destino_adelanto" IN ('devuelto', 'retenido'));